export async function getApiKeysByUserId(userId: number): Promise<Partial<ApiKey>[]> {
  const { data, error } = await supabase
    .from('api_keys')
    .select('id, key_prefix, name, is_active, last_used_at, created_at')
    .eq('user_id', userId);

  if (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[Supabase] Error getting API keys');
    return [];
  }
  return data || [];
}

