// ============ Rate Limiting Functions ============

export async function checkRateLimit(userId: number, plan: string): Promise<{
  allowed: boolean;
  remaining: number;
  resetAt: Date;
}> {
  const planLimits: Record<string, { calls: number; rate: number }> = {
    free: { calls: 2000, rate: 10 },
    builder: { calls: 25000, rate: 60 },
    startup: { calls: 150000, rate: 300 },
    scale: { calls: 500000, rate: 1000 },
    business: { calls: 2000000, rate: 5000 },
    enterprise: { calls: Infinity, rate: 10000 },
    enterprise_plus: { calls: Infinity, rate: 50000 },
  };

  const limits = planLimits[plan] || planLimits.free;
  const key = `rate:${userId}`;
  const now = new Date();
  const _windowStart = new Date(now.getTime() - 60000); // 1 minute window (reserved for windowed rate-limit)

  // Get or create rate limit record
  const { data: existing } = await supabase
    .from('rate_limits')
    .select('*')
    .eq('key', key)
    .gte('expires_at', now.toISOString())
    .single();

  if (existing) {
    const allowed = existing.count < limits.rate;
    if (allowed) {
      await supabase
        .from('rate_limits')
        .update({ count: existing.count + 1 })
        .eq('id', existing.id);
    }
    return {
      allowed,
      remaining: Math.max(0, limits.rate - existing.count - 1),
      resetAt: new Date(existing.expires_at),
    };
  }

  // Create new rate limit window
  const expiresAt = new Date(now.getTime() + 60000);
  await supabase
    .from('rate_limits')
    .insert({
      key,
      count: 1,
      window_start: now.toISOString(),
      expires_at: expiresAt.toISOString(),
    });

  return {
    allowed: true,
    remaining: limits.rate - 1,
    resetAt: expiresAt,
  };
}

// ============ Leads Functions ============

function calculateLeadScore(data: {
  escalationRisk?: number;
  churnProbability?: number;
  valueAtRisk?: number;
}): { score: number; tier: 'cold' | 'warm' | 'hot' | 'qualified' } {
  let score = 0;

  if (data.escalationRisk) {
    score += Math.round(data.escalationRisk * 0.4);
  }
  if (data.churnProbability) {
    score += Math.round(data.churnProbability * 0.3);
  }
  if (data.valueAtRisk) {
    const valueScore = Math.min(data.valueAtRisk / 10000, 1) * 30;
    score += Math.round(valueScore);
  }

  let tier: 'cold' | 'warm' | 'hot' | 'qualified';
  if (score >= 70) tier = 'qualified';
  else if (score >= 50) tier = 'hot';
  else if (score >= 30) tier = 'warm';
  else tier = 'cold';

  return { score, tier };
}

export async function createLead(leadData: {
  email: string;
  companyName?: string | null;
  companySize?: string | null;
  industry?: string | null;
  sourcePage?: string | null;
  utmSource?: string | null;
  utmMedium?: string | null;
  utmCampaign?: string | null;
  escalationRisk?: number | null;
  churnProbability?: number | null;
  valueAtRisk?: number | null;
}): Promise<Lead | null> {
  const { score, tier } = calculateLeadScore({
    escalationRisk: leadData.escalationRisk ?? undefined,
    churnProbability: leadData.churnProbability ?? undefined,
    valueAtRisk: leadData.valueAtRisk ?? undefined,
  });

  const { data, error } = await supabase
    .from('leads')
    .insert({
      email: leadData.email.toLowerCase(),
      company_name: leadData.companyName ?? null,
      company_size: leadData.companySize ?? null,
      industry: leadData.industry ?? null,
      source_page: leadData.sourcePage ?? null,
      utm_source: leadData.utmSource ?? null,
      utm_medium: leadData.utmMedium ?? null,
      utm_campaign: leadData.utmCampaign ?? null,
      escalation_risk: leadData.escalationRisk ?? null,
      churn_probability: leadData.churnProbability ?? null,
      value_at_risk: leadData.valueAtRisk ?? null,
      lead_score: score,
      lead_tier: tier,
      status: 'new',
    })
    .select()
    .single();

  if (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[Supabase] Error creating lead');
    return null;
  }
  return data;
}

