export async function getLeadStats(): Promise<{
  total: number;
  byStatus: Record<string, number>;
  byTier: Record<string, number>;
  avgScore: number;
  todayCount: number;
}> {
  const { data: leads, error } = await supabase
    .from('leads')
    .select('status, lead_tier, lead_score, created_at');

  if (error || !leads) {
    return { total: 0, byStatus: {}, byTier: {}, avgScore: 0, todayCount: 0 };
  }

  const today = new Date();
  today.setHours(0, 0, 0, 0);

  const byStatus: Record<string, number> = {};
  const byTier: Record<string, number> = {};
  let totalScore = 0;
  let todayCount = 0;

  leads.forEach(lead => {
    byStatus[lead.status] = (byStatus[lead.status] || 0) + 1;
    if (lead.lead_tier) {
      byTier[lead.lead_tier] = (byTier[lead.lead_tier] || 0) + 1;
    }
    totalScore += lead.lead_score || 0;
    if (new Date(lead.created_at) >= today) {
      todayCount++;
    }
  });

  return {
    total: leads.length,
    byStatus,
    byTier,
    avgScore: leads.length > 0 ? Math.round(totalScore / leads.length) : 0,
    todayCount,
  };
}

