export async function updateSubscriptionByStripeId(
  stripeSubscriptionId: string,
  updates: {
    plan?: string;
    status?: string;
    currentPeriodStart?: Date | null;
    currentPeriodEnd?: Date | null;
    cancelAtPeriodEnd?: boolean;
  }
): Promise<boolean> {
  const updateData: Record<string, unknown> = {};

  if (updates.plan !== undefined) {
    updateData.plan = updates.plan;
  }
  if (updates.status !== undefined) {
    updateData.status = updates.status;
  }
  if (updates.currentPeriodStart !== undefined) {
    updateData.currentPeriodStart = updates.currentPeriodStart?.toISOString() ?? null;
  }
  if (updates.currentPeriodEnd !== undefined) {
    updateData.currentPeriodEnd = updates.currentPeriodEnd?.toISOString() ?? null;
  }
  if (updates.cancelAtPeriodEnd !== undefined) {
    updateData.cancelAtPeriodEnd = updates.cancelAtPeriodEnd;
  }
  updateData.updatedAt = new Date().toISOString();

  const { error } = await supabase
    .from('subscriptions')
    .update(updateData)
    .eq('stripeSubscriptionId', stripeSubscriptionId);

