        </div>

        {/* Main Content */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          {/* Left: Tabs */}
          <div className="lg:col-span-2">
            <Tabs defaultValue="api-keys" id="api-keys">
              <TabsList className="grid grid-cols-3 w-full">
                <TabsTrigger value="api-keys" className="gap-1.5">
                  <Key className="h-3.5 w-3.5" /> API Keys
                </TabsTrigger>
                <TabsTrigger value="usage" className="gap-1.5">
                  <BarChart3 className="h-3.5 w-3.5" /> Usage
                </TabsTrigger>
                <TabsTrigger value="billing" className="gap-1.5">
                  <CreditCard className="h-3.5 w-3.5" /> Billing
                </TabsTrigger>
              </TabsList>

              {/* API Keys Tab */}
              <TabsContent value="api-keys" className="mt-4 space-y-3">
                <div className="flex items-center justify-between">
                  <div>
                    <h3 className="text-sm font-semibold">API Keys</h3>
                    <p className="text-xs text-muted-foreground">Use these keys to authenticate requests to the Gravito API.</p>
                  </div>
                  <Dialog open={createDialogOpen} onOpenChange={setCreateDialogOpen}>
                    <DialogTrigger asChild>
                      <Button size="sm" className="gap-1.5">
                        <Plus className="h-3.5 w-3.5" /> New key
                      </Button>
                    </DialogTrigger>
                    <DialogContent>
                      <DialogHeader>
                        <DialogTitle>Create API key</DialogTitle>
                        <DialogDescription>
                          Give your key a name to identify where it's used (e.g. "Production", "CI/CD").
                        </DialogDescription>
                      </DialogHeader>
                      <div className="space-y-2 py-2">
                        <Label htmlFor="key-name">Key name (optional)</Label>
                        <Input
                          aria-label="e.g. Production" id="key-name"
                          placeholder="e.g. Production"
                          value={newKeyName}
                          onChange={(e) => setNewKeyName(e.target.value)}
                        />
                      </div>
                      <DialogFooter>
                        <Button variant="outline" onClick={() => setCreateDialogOpen(false)}>Cancel</Button>
                        <Button
                          onClick={() => createKey.mutate({ name: newKeyName || undefined })}
                          disabled={createKey.isPending}
                        >
                          {createKey.isPending ? <Loader2 className="h-4 w-4 animate-spin mr-2" /> : null}
                          Create key
                        </Button>
                      </DialogFooter>
                    </DialogContent>
                  </Dialog>
                </div>

                {keysLoading ? (
                  <div className="space-y-2">
                    {[1, 2].map(i => <div key={i} className="h-16 bg-muted animate-pulse rounded-lg" />)}
