import { generalLog } from './_core/logger';
import { createClient } from '@supabase/supabase-js';

// Supabase configuration — CQ1 fix: read from env vars with hardcoded fallback
const SUPABASE_URL = process.env.SUPABASE_URL || 'https://cxpzxwcglkwegxyyffwc.supabase.co';
const SUPABASE_ANON_KEY = process.env.SUPABASE_ANON_KEY || 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImN4cHp4d2NnbGt3ZWd4eXlmZndjIiwicm9sZSI6ImFub24iLCJpYXQiOjE3Njk1Njc1NDAsImV4cCI6MjA4NTE0MzU0MH0.B1qyqeiqTNVtLPGUv2NsfujUVTNmEOlJFJL1xLigBtQ';
const SUPABASE_SERVICE_ROLE_KEY = process.env.SUPABASE_SERVICE_ROLE_KEY || 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImN4cHp4d2NnbGt3ZWd4eXlmZndjIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc2OTU2NzU0MCwiZXhwIjoyMDg1MTQzNTQwfQ.tm1v-cBGedQF6v4-blMCCTeZauC6TbudSP5Bn8SSU3g';

// Create Supabase client with service role for server-side operations
// Service role bypasses Row Level Security (RLS) - use only on server
export const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY, {
  auth: {
    autoRefreshToken: false,
    persistSession: false,
  },
});

// Create anon client for client-side operations (respects RLS)
export const supabaseAnon = createClient(SUPABASE_URL, SUPABASE_ANON_KEY);

// Export configuration for use elsewhere
export const supabaseConfig = {
  url: SUPABASE_URL,
  anonKey: SUPABASE_ANON_KEY,
  serviceRoleKey: SUPABASE_SERVICE_ROLE_KEY,
};

// Database table types (matching existing Drizzle schema)
export interface User {
  id: number;
  openId: string;
  name: string;
  email: string;
  password: string | null;
  avatarUrl: string | null;
  role: 'admin' | 'user';
  stripeCustomerId: string | null;
  currentPlan: string;
  apiKey: string | null;
  apiKeyCreatedAt: Date | null;
  apiCallsThisMonth: number;
  apiCallsTotal: number;
  lastApiCallAt: Date | null;
  createdAt: Date;
  updatedAt: Date;
}

export interface ApiUsage {
  id: number;
  userId: number;
  endpoint: string;
  method: string;
  statusCode: number;
  responseTimeMs: number;
  tokensUsed: number | null;
  createdAt: Date;
}

export interface BillingHistory {
  id: number;
  userId: number;
  stripeInvoiceId: string | null;
  stripePaymentIntentId: string | null;
  amount: number;
  currency: string;
  status: string;
  description: string | null;
  createdAt: Date;
}

export interface RateLimit {
  id: number;
  key: string;
  count: number;
  windowStart: Date;
  expiresAt: Date;
}

// Helper functions for Supabase operations
export async function testConnection(): Promise<boolean> {
  try {
    const { data, error } = await supabase.from('users').select('count').limit(1);
    if (error) {
      generalLog.error('Supabase connection test failed:', error.message);
      return false;
    }
    generalLog.info('Supabase connection successful');
    return true;
  } catch (err) {
    generalLog.error('Supabase connection error:', err);
    return false;
  }
}

