/**
 * The fields `getApiKeysByUserId` returns. It is a strict subset of ApiKey — the
 * key hash and owning user id are deliberately never selected — but every field
 * in the subset is always present, so consumers don't have to guard for absence.
 */
export type ApiKeySummary = Pick<ApiKey, 'id' | 'keyPrefix' | 'name' | 'isActive' | 'lastUsedAt' | 'createdAt'>;

export async function getApiKeysByUserId(userId: number): Promise<ApiKeySummary[]> {
  const keys = await supabaseDb.getApiKeysByUserId(userId);
  return keys.map(k => ({
    id: k.id,
    keyPrefix: k.key_prefix,
    name: k.name,
    isActive: k.is_active,
    lastUsedAt: k.last_used_at,
    createdAt: k.created_at,
  }));
}

